int dvb_usb_suspend(struct usb_interface *intf, pm_message_t msg)
{
    struct dvb_usb_device *d;
    int ret = 0;

    d = usb_get_intfdata(intf);
    if (!d)
        return -ENODEV;

    if (d->rc_ctrl)
        dvb_usb_rc_polling_stop(d);

    mutex_lock(&d->mutex);
    if (d->adapter) {
        if (d->adapter->frontend && d->adapter->frontend->fe) {
            dvb_frontend_stop(d->adapter->frontend->fe);
            d->adapter->frontend->fe->ops.release(d->adapter->frontend->fe);
        }
    }
    mutex_unlock(&d->mutex);

    d->state &= ~DVB_USB_STATE_ACTIVE;
    set_bit(FLAGS_SUSPENDED, &d->flags);

    return ret;
}

