    int ret = 0;

    if (!d)
        return -ENODEV;

    /* Stop remote controller polling */
    if (d->rc_polling) {
        d->rc_polling = 0;
        wait_for_completion(&d->rc_poll_wq);
    }

    /* Iterate over adapters and stop streaming */
    if (d->num_adapters) {
        int i;
        for (i = 0; i < d->num_adapters; i++) {
            struct dvb_adapter *adapter = &d->adapter[i];
            if (adapter->frontend) {
                if (adapter->frontend->info.ops->frontend->stop_feed)
                    adapter->frontend->info.ops->frontend->stop_feed(adapter->frontend);
                adapter->fe_status |= FE_SUSPENDED;
            }
        }
    }

