int dvb_usb_suspend(struct usb_interface *intf, pm_message_t msg) {
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int ret = 0;

    if (!d)
        return -ENODEV;

    /* Cancel any active remote controller polling */
    if (d->rc) {
        dvb_usb_rc_query(d, NULL, true);
        cancel_delayed_work(&d->rc_work);
    }

    /* Stop streaming and suspend each frontend */
    for (int i = 0; i < d->num_adapters; i++) {
        struct dvb_adapter *adapter = d->adapters[i].adapter;

        if (adapter && d->adapters[i].frontend) {
            d->adapters[i].frontend->stop_feed(d->adapters[i].frontend);
            dvb_frontend_suspend(d->adapters[i].frontend);
        }
    }

    return ret;
}

int dvb_usb_suspend(struct usb_interface *intf, pm_message_t msg)
{
    struct dvb_usb_device *d = usb_get_intfdata(intf);
    int ret = 0;

    if (!d)
        return -ENODEV;

    /* Stop remote controller polling */
    if (d->rc_polling_active) {
        cancel_work_sync(&d->rc_poll_work);
        d->rc_polling_active = 0;
    }

    /* Stop streaming and suspend frontends */
    for (int i = 0; i < d->num_adapters; i++) {
        struct dvb_adapter *adapter = &d->adapters[i];

        if (adapter->active_frontend) {
            ret = adapter->ops.frontend->stop(adapter->active_frontend);
            if (ret < 0)
                continue;

            ret = adapter->ops.frontend->suspend(adapter->active_frontend);
            if (ret < 0)
                continue;

            adapter->active_frontend->state |= DVBFE_SUSPENDED;
        }
    }

    return ret;
}
